import React, { useState } from 'react';

function App() {
  const [rating, setRating] = useState(3);
  const [comment, setComment] = useState('');
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = () => {
    setSubmitted(true);
  };

  return (
    <div className="container">
      <h1>Оцінка програмного уроку</h1>
      <label>Оцінка (1-5):</label>
      <input type="range" min="1" max="5" value={rating} onChange={(e) => setRating(e.target.value)} />
      <div className="range-value">{rating}</div>

      <label>Коментар:</label>
      <textarea placeholder="Напишіть ваш відгук..." value={comment} onChange={(e) => setComment(e.target.value)} />

      <button onClick={handleSubmit}>Надіслати</button>

      {submitted && (
        <div className="result">
          <h2>Дякуємо!</h2>
          <p>Оцінка: {rating}</p>
          <p>Коментар: {comment}</p>
        </div>
      )}
    </div>
  );
}

export default App;
